    {
      "id": "classifyEscalation1",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {
        "label": "Classify Escalation"
      },
      "inputs": {
        "script": "const email = $vars.newEmailReceived1.output;
const importance = (email.importance || '').toLowerCase();
const subject = (email.subject || '').toLowerCase();
const bodyContent = ((email.body || {}).content || '').toLowerCase();
const urgentKeywords = ['urgent', 'asap', 'immediately', 'critical', 'emergency', 'down'];
const isUrgent = importance === 'high' || urgentKeywords.some(k => subject.includes(k) || bodyContent.includes(k));

